// generated by build.mjs from ../examples/*.js
export const EXAMPLES = [{"id":"F-01","title":"Blinky","group":"Basics","about":"One module on the pico board. A timer flips the LED every 250 ms. A signal written in a timed or clocked block is a register; the compiler sizes the prescaler from the board's 12 MHz clock.","shows":["design","module",".out()",".every()",".bind()","a scenario on the simulated board"],"watch":"Board · Waves","tries":["Blink at 5 Hz","Drive all three LEDs as a counter"],"file":"F-01-blinky.js","text":"/** F-01 Blinky\n *  group  Basics\n *  about  One module on the pico board. A timer flips the LED every 250 ms. A signal written in a timed or clocked\n *         block is a register; the compiler sizes the prescaler from the board's 12 MHz clock.\n *  shows  design · module · .out() · .every() · .bind() · a scenario on the simulated board\n *  watch  Board · Waves\n *  try    Blink at 5 Hz | Drive all three LEDs as a counter\n */\nconst blink = module(\"blink\")\n  .out(\"led\", bit)\n  .every(\"250ms\", $ => { $.led = !$.led; })         // 12 MHz × 250 ms: a 22-bit prescaler, generated for you\n  .bind({ led: \"led:0\" });\n\nreturn design(\"blinky\")\n  .board(\"pico\")\n  .use(blink)\n  .scenario(\"blinks at 2 Hz\", sc => sc\n    .wait(\"1.1s\")\n    .expectToggles(\"led:0\", n => n === 4));\n"},{"id":"F-02","title":"Counter","group":"Basics","about":"A ticker and an up/down counter, wired by name and shown on eight LEDs. Arithmetic grows: an 8-bit value plus one is nine bits, and putting it back into eight bits takes a word, wrap() or sat(). Compound assignments (+=, -=) wrap by definition.","shows":["ports",".seq() and .comb()","pulse",".wire() and .pins()","width rules","board- and signal-level scenarios"],"watch":"Board · Waves","tries":["Replace wrap() with sat() and stop at 255","Write $.value = $.value + 1 and read the error"],"file":"F-02-counter.js","text":"/** F-02 Counter\n *  group  Basics\n *  about  A ticker and an up/down counter, wired by name and shown on eight LEDs. Arithmetic grows: an 8-bit value\n *         plus one is nine bits, and putting it back into eight bits takes a word, wrap() or sat(). Compound\n *         assignments (+=, -=) wrap by definition.\n *  shows  ports · .seq() and .comb() · pulse · .wire() and .pins() · width rules · board- and signal-level scenarios\n *  watch  Board · Waves\n *  try    Replace wrap() with sat() and stop at 255 | Write $.value = $.value + 1 and read the error\n */\nconst ticker = module(\"ticker\")\n  .out(\"tick\", pulse)                               // a pulse is a bit that falls back to 0 on its own\n  .every(\"100ms\", $ => { $.tick = 1; });\n\nconst counter = module(\"counter\")\n  .in({ en: bit, down: bit })\n  .out({ value: u(8), zero: bit })\n  .seq($ => {                                       // written here, value is a register: reset to 0, synchronous\n    if ($.en) $.value = wrap($.down ? $.value - 1 : $.value + 1);\n  })\n  .comb($ => { $.zero = $.value === 0; });         // written here, zero is a wire\n\nreturn design(\"counter\")\n  .board(\"dev\")\n  .use(ticker, counter)\n  .wire(\"ticker.tick\", \"counter.en\")\n  .pins({ \"counter.down\": \"sw:0\", \"counter.value\": \"led:0..7\" })\n  .scenario(\"counts up, then down\", sc => sc\n    .wait(\"350ms\").expectPins(\"led:0..7\", 3)\n    .toggle(\"sw:0\").wait(\"300ms\").expectPins(\"led:0..7\", 0))\n  .scenario(\"wraps below zero\", sc => sc\n    .poke(\"counter.down\", 1).poke(\"counter.en\", 1).step()\n    .expectSignal(\"counter.value\", 255)\n    .expectSignal(\"counter.zero\", 0));\n"},{"id":"F-03","title":"Three kinds of lambda","group":"Basics","about":"Builder lambdas run once, now, in JS, and shape the graph. Hardware lambdas are parsed into the IR and never called, so they cannot see JS variables: whatever they need is shipped with .lib(). Runtime lambdas run later, beside the simulator or the board, and are ordinary JS. This example ships with the classic mistake.","shows":["the compiler's capture check",".lib()","arrays become ROMs, functions are re-parsed and inlined"],"watch":"Code (diagnostics)","tries":["Fix the capture error","Explain why gamma needs GAMMA shipped too"],"file":"F-03-lambdas.js","text":"/** F-03 Three kinds of lambda\n *  group  Basics\n *  about  Builder lambdas run once, now, in JS, and shape the graph. Hardware lambdas are parsed into the IR and\n *         never called, so they cannot see JS variables: whatever they need is shipped with .lib(). Runtime lambdas\n *         run later, beside the simulator or the board, and are ordinary JS. This example ships with the classic\n *         mistake.\n *  shows  the compiler's capture check · .lib() · arrays become ROMs, functions are re-parsed and inlined\n *  watch  Code (diagnostics)\n *  try    Fix the capture error | Explain why gamma needs GAMMA shipped too\n */\nconst GAMMA = Array.from({ length: 256 }, (_, i) => Math.round(255 * (i / 255) ** 2.2));   // build-time JS\nconst gamma = v => GAMMA[v];\n\nconst dimmer = module(\"dimmer\")\n  .in(\"level\", u(8))\n  .out(\"pwm\", bit)\n  .regs({ phase: u(8) })\n  .budget(b => b.luts(120).brams(0))                // builder lambda: runs now, while the graph is built\n  .seq($ => {                                       // hardware lambda: parsed into IR nodes, never called\n    $.phase += 1;\n    $.pwm = $.phase < gamma($.level);              // ✕ captures the JS binding `gamma`\n  });\n  // the fix: .lib({ GAMMA, gamma }). GAMMA becomes a 256 × 8 ROM; gamma is re-parsed and inlined at the call\n\nreturn design(\"lambdas\")\n  .board(\"dev\")\n  .use(dimmer)\n  .pins({ \"dimmer.level\": \"sw:0..7\", \"dimmer.pwm\": \"led:0\" })\n  .scenario(\"half the switches, a fifth of the light\", async tb => {   // runtime lambda: plain async JS\n    await tb.set(\"sw:0..7\", 128);\n    const duty = await tb.measure(\"led:0\", { over: \"1ms\" });          // the fraction of time it was high\n    tb.expect(Math.abs(duty - GAMMA[128] / 256) < 0.01);              // runtime lambdas may use JS values freely\n  });\n"},{"id":"F-04","title":"Parameters and generators","group":"Basics","about":"Builders are values: every call returns a new one, so a module can be shared, specialized with .with() and stamped out in a plain JS loop. Any builder argument may be a lambda of the parameters; it runs once per specialization. Parameters reach hardware lambdas as constants, so loops over them unroll.","shows":[".params()",".with()",".as()","builder lambdas of params","unrolled loops","\"generate\" is just JS"],"watch":"DAG (instances)","tries":["Make channel 7 a 12-bit PWM","Put the eight phases 45° apart"],"file":"F-04-generators.js","text":"/** F-04 Parameters and generators\n *  group  Basics\n *  about  Builders are values: every call returns a new one, so a module can be shared, specialized with .with()\n *         and stamped out in a plain JS loop. Any builder argument may be a lambda of the parameters; it runs once\n *         per specialization. Parameters reach hardware lambdas as constants, so loops over them unroll.\n *  shows  .params() · .with() · .as() · builder lambdas of params · unrolled loops · \"generate\" is just JS\n *  watch  DAG (instances)\n *  try    Make channel 7 a 12-bit PWM | Put the eight phases 45° apart\n */\nconst pwm = module(\"pwm\")\n  .params({ BITS: 8 })\n  .in(\"duty\", ({ BITS }) => u(BITS))                // a builder lambda of params: runs per specialization\n  .out(\"out\", bit)\n  .regs(({ BITS }) => ({ phase: u(BITS) }))\n  .seq($ => {\n    $.phase += 1;\n    $.out = $.phase < $.duty;\n  });\n\nconst breathe = module(\"breathe\")\n  .params({ N: 4 })\n  .out(\"duty\", ({ N }) => vec(u(8), N))\n  .regs({ level: u(8), up: bit.init(1) })\n  .every(\"4ms\", $ => {\n    const up = $.level === 0 ? 1 : $.level === 255 ? 0 : $.up;   // locals are wires\n    $.up = up;\n    if (up) $.level += 1;\n    else $.level -= 1;\n  })\n  .comb($ => {\n    for (let i = 0; i < N; i++) $.duty[i] = wrap($.level + i * 32);   // N is a constant here, so the loop unrolls\n  });\n\nconst bank = Array.from({ length: 8 }, (_, i) => pwm.as(`pwm-${i}`));   // eight instances of one value\n\nreturn design(\"breathing\")\n  .board(\"dev\")\n  .use(breathe.with({ N: bank.length }), ...bank)\n  .wire(bank.map((p, i) => [`breathe.duty[${i}]`, `${p.name}.duty`]))\n  .pins(Object.fromEntries(bank.map((p, i) => [`${p.name}.out`, `led:${i}`])))\n  .scenario(\"eight different phases\", sc => sc\n    .wait(\"300ms\")\n    .expectSignal(\"breathe.duty\", d => new Set(d).size === 8));\n"},{"id":"F-05","title":"Buttons and events","group":"Components","about":"std.debounce cleans four raw buttons and provides a stream of presses. The lights module needs that stream; the link pass connects producer to consumer by name, with no wiring written. Handlers fire on stream beats and on edges of input ports.","shows":["std components",".provides() / .needs()",".on(stream)",".on(\"port.rise\")","exclusive pin binding"],"watch":"Board · DAG (links)","tries":["Bind a second module to led:0..7 and read the error","Clear on a double press instead of a long one"],"file":"F-05-buttons.js","text":"/** F-05 Buttons and events\n *  group  Components\n *  about  std.debounce cleans four raw buttons and provides a stream of presses. The lights module needs that\n *         stream; the link pass connects producer to consumer by name, with no wiring written. Handlers fire on\n *         stream beats and on edges of input ports.\n *  shows  std components · .provides() / .needs() · .on(stream) · .on(\"port.rise\") · exclusive pin binding\n *  watch  Board · DAG (links)\n *  try    Bind a second module to led:0..7 and read the error | Clear on a double press instead of a long one\n */\nconst buttons = std.debounce(\"buttons\")\n  .bind({ raw: \"btn:0..3\" })\n  .settle(\"10ms\")                                   // an edge must hold for 10 ms to count\n  .longPress(\"500ms\")                               // presses carry { id: u(2), long: bit }\n  .provides(\"presses\");\n\nconst lights = module(\"lights\")\n  .needs(\"presses\")\n  .in(\"invert\", bit)\n  .out(\"leds\", u(8))\n  .on(\"presses\", ($, p) => {                        // runs on the cycle a beat arrives; ready is handled for you\n    $.leds = p.long ? 0 : $.leds ^ (1 << p.id);\n  })\n  .on(\"invert.rise\", $ => { $.leds = ~$.leds; })    // an edge of an input port is an event too\n  .bind({ invert: \"sw:0\", leds: \"led:0..7\" });      // led:0..7 now belongs to lights; a second binder is an error\n\nreturn design(\"lights\")\n  .board(\"dev\")\n  .use(buttons, lights)                             // no .wire(): \"presses\" links by name\n  .scenario(\"toggle, invert, clear\", sc => sc\n    .press(\"btn:2\").wait(\"20ms\").expectPins(\"led:0..7\", 0b0000_0100)\n    .press(\"btn:0\", { bounce: \"3ms\" }).wait(\"20ms\").expectPins(\"led:0..7\", 0b0000_0101)   // chatter counts once\n    .toggle(\"sw:0\").wait(\"1ms\").expectPins(\"led:0..7\", 0b1111_1010)\n    .press(\"btn:1\", { for: \"600ms\" }).wait(\"20ms\").expectPins(\"led:0..7\", 0));\n"},{"id":"F-06","title":"State machines","group":"Components","about":"A UART transmitter written as an fsm. Each state is a hardware lambda: it drives outputs, writes registers and returns the next state; returning nothing stays put. fsm.extract reads the returns to build the transition graph, and fsm.encode picks an encoding for the part.","shows":["fsm()","states as lambdas",".lib() from params and the clock","a hardware helper","$.has() / $.take()"],"watch":"DAG (fsm) · Board (serial)","tries":["Add an even-parity state","Force .encode(\"onehot\") and compare LUTs in the report"],"file":"F-06-fsm.js","text":"/** F-06 State machines\n *  group  Components\n *  about  A UART transmitter written as an fsm. Each state is a hardware lambda: it drives outputs, writes\n *         registers and returns the next state; returning nothing stays put. fsm.extract reads the returns to\n *         build the transition graph, and fsm.encode picks an encoding for the part.\n *  shows  fsm() · states as lambdas · .lib() from params and the clock · a hardware helper · $.has() / $.take()\n *  watch  DAG (fsm) · Board (serial)\n *  try    Add an even-parity state | Force .encode(\"onehot\") and compare LUTs in the report\n */\nconst greeter = module(\"greeter\")\n  .provides(\"bytes\")\n  .lib({ MSG: [...\"hello\\r\\n\"].map(ch => ch.charCodeAt(0)) })   // an array of numbers becomes a 7-entry ROM\n  .regs({ i: u(3), go: bit })\n  .every(\"1s\", $ => { $.go = 1; })\n  .seq($ => {\n    if ($.go && $.push(\"bytes\", MSG[$.i])) {        // push() is 1 on the cycle the beat is taken\n      if ($.i === MSG.length - 1) { $.i = 0; $.go = 0; }\n      else $.i += 1;\n    }\n  });\n\nfunction baud($) {                                  // a hardware helper: shipped by .lib(), inlined where called\n  if ($.wait !== 0) { $.wait -= 1; return 0; }\n  $.wait = DIV;\n  return 1;\n}\n\nconst tx = fsm(\"uart-tx\")\n  .params({ BAUD: 115_200 })\n  .needs(\"bytes\")\n  .out(\"line\", bit.init(1))                         // a UART line idles high\n  .regs({ shift: u(8), n: u(3), wait: u(16) })\n  .lib(({ BAUD }, { clock }) => ({ DIV: Math.round(clock.hz / BAUD) - 1 }))   // builder lambda: params and clock\n  .lib({ baud })\n  .initial(\"idle\")\n  .state(\"idle\", $ => {\n    $.line = 1;\n    if ($.has(\"bytes\")) { $.shift = $.take(\"bytes\"); $.wait = DIV; return \"start\"; }\n  })\n  .state(\"start\", $ => { $.line = 0; if (baud($)) return \"data\"; })\n  .state(\"data\", $ => {\n    $.line = $.shift[0];\n    if (!baud($)) return;\n    $.shift >>= 1;\n    $.n += 1;                                       // wraps back to 0 after the eighth bit\n    if ($.n === 7) return \"stop\";\n  })\n  .state(\"stop\", $ => { $.line = 1; if (baud($)) return \"idle\"; });\n\nreturn design(\"hello-uart\")\n  .board(\"pico\")                                    // 12 MHz, so DIV = 103\n  .use(stream(\"bytes\").of(u(8)).buffer(8, { overflow: \"block\" }), greeter, tx)\n  .pins({ \"uart-tx.line\": \"uart.tx\" })\n  .scenario(\"says hello every second\", sc => sc\n    .expectUart(\"uart\", \"hello\\r\\n\", { within: \"1.1s\", baud: 115_200 })\n    .expectUart(\"uart\", \"hello\\r\\n\", { within: \"1.1s\", baud: 115_200 }));\n"},{"id":"F-07","title":"Backpressure","group":"Components","about":"Four fast producers, four slow consumers, four buffered streams with four overflow policies. \"block\" holds ready low and its producer waits; the lossy ones keep going and count what they drop, in hardware, where the host can read it. stream.lower picks each buffer's implementation from its depth.","shows":["stream().buffer() overflow policies","$.push() / $.has() / $.take()","generator loops","drop counters"],"watch":"DAG (queues) · Waves","tries":["Make one consumer twice as fast","Give q.block a depth of 512 and watch it move to block RAM"],"file":"F-07-backpressure.js","text":"/** F-07 Backpressure\n *  group  Components\n *  about  Four fast producers, four slow consumers, four buffered streams with four overflow policies. \"block\"\n *         holds ready low and its producer waits; the lossy ones keep going and count what they drop, in hardware,\n *         where the host can read it. stream.lower picks each buffer's implementation from its depth.\n *  shows  stream().buffer() overflow policies · $.push() / $.has() / $.take() · generator loops · drop counters\n *  watch  DAG (queues) · Waves\n *  try    Make one consumer twice as fast | Give q.block a depth of 512 and watch it move to block RAM\n */\nconst policies = {\n  \"q.block\":  { depth: 16, overflow: \"block\" },\n  \"q.oldest\": { depth: 16, overflow: \"drop-oldest\" },\n  \"q.newest\": { depth: 16, overflow: \"drop-newest\" },\n  \"q.latest\": { depth: 1,  overflow: \"latest\" },      // a register: the consumer always sees the freshest value\n};\nconst names = Object.keys(policies);\n\nconst queues = names.map(n => stream(n)             // depth 1 → a register, 16 → LUT RAM, ≥ 64 → block RAM\n  .of(u(16))\n  .buffer(policies[n].depth, { overflow: policies[n].overflow }));\n\nconst producers = names.map(n => module(`fast-${n.slice(2)}`)\n  .provides(n)\n  .lib({ Q: n })                                    // a constant string names the stream inside the lambda\n  .regs({ seq: u(16) })\n  .seq($ => { if ($.push(Q, $.seq)) $.seq += 1; })); // a lossy stream always accepts; \"block\" may not\n\nconst consumers = names.map(n => module(`slow-${n.slice(2)}`)\n  .needs(n)\n  .lib({ Q: n })\n  .regs({ last: u(16).init(0xffff), gaps: u(16), busy: u(2) })\n  .seq($ => {\n    $.busy += 1;                                    // ready on one cycle in four\n    if ($.busy === 0 && $.has(Q)) {\n      const v = $.take(Q);\n      if (v !== wrap($.last + 1)) $.gaps += 1;\n      $.last = v;\n    }\n  }));\n\nreturn design(\"backpressure\")\n  .board(\"dev\")\n  .use(...queues, ...producers, ...consumers)\n  .scenario(\"only block is lossless\", sc => sc\n    .step(4000)\n    .expectState(\"slow-block\", s => s.gaps === 0)\n    .expectState(\"slow-oldest\", s => s.gaps > 0)\n    .expectState(\"slow-latest\", s => s.gaps > 0)\n    .expectDropped(\"q.block\", 0)\n    .expectDropped(\"q.newest\", n => n > 2000));\n"},{"id":"F-08","title":"Tables and memories","group":"Components","about":"A direct digital synthesizer feeding an echo. A builder lambda fills the sine table; the delay line is a RAM that mem.infer puts in block RAM. RAM reads take a cycle, and the grammar makes you say so.","shows":["rom().from()",".ram()",".every(\"48 kHz\")","sat()","std.sigmaDelta","a check on the build report"],"watch":"Board (audio) · Report (memories)","tries":["Store a quarter wave and mirror it","Make the echo half a second long and read the BRAM count"],"file":"F-08-memories.js","text":"/** F-08 Tables and memories\n *  group  Components\n *  about  A direct digital synthesizer feeding an echo. A builder lambda fills the sine table; the delay line is a\n *         RAM that mem.infer puts in block RAM. RAM reads take a cycle, and the grammar makes you say so.\n *  shows  rom().from() · .ram() · .every(\"48 kHz\") · sat() · std.sigmaDelta · a check on the build report\n *  watch  Board (audio) · Report (memories)\n *  try    Store a quarter wave and mirror it | Make the echo half a second long and read the BRAM count\n */\nconst sine = rom(\"sine\")\n  .of(s(12))\n  .from(1024, i => Math.round(2047 * Math.sin((2 * Math.PI * i) / 1024)));   // builder lambda, called 1024 times now\n\nconst osc = module(\"osc\")\n  .params({ HZ: 440 })\n  .provides(\"dry\")\n  .lib({ SINE: sine })                              // a rom shipped by .lib() is instanced in this module\n  .lib(({ HZ }) => ({ STEP: Math.round((HZ * 2 ** 32) / 48_000) }))   // the tuning word, computed at build time\n  .regs({ phase: u(32) })\n  .every(\"48 kHz\", $ => {\n    $.phase += STEP;\n    $.push(\"dry\", SINE[$.phase.bits(31, 22)]);      // the top ten bits index the table\n  });\n\nconst echo = module(\"echo\")\n  .needs(\"dry\").provides(\"wet\")\n  .ram(\"delay\", { of: s(12), words: 8192 })         // 8192 × 12 bits\n  .regs({ at: u(13) })\n  .on(\"dry\", ($, x) => {\n    const back = $.delay.q;                         // what the last read() returned: reads take a cycle\n    const y = sat(x + (back >> 1), s(12));          // 13 bits back into 12 by saturating, never by accident\n    $.delay.write($.at, y);\n    $.delay.read(wrap($.at + 1));                   // the oldest sample, ready by the next beat\n    $.at += 1;\n    $.push(\"wet\", y);\n  });\n\nreturn design(\"echo\")\n  .board(\"dev\")\n  .use(stream(\"dry\").of(s(12)), stream(\"wet\").of(s(12)), osc, echo)\n  .use(std.sigmaDelta(\"dac\").needs(\"wet\").bind({ out: \"audio\" }))\n  .compile(c => c                                   // the default pipeline, plus one check (more in F-13)\n    .check(\"the delay line is block RAM\", r => r.resources.of(\"echo\").brams >= 1))\n  .scenario(\"stays in range\", sc => sc\n    .wait(\"200ms\")\n    .expectStream(\"wet\", ys => ys.every(y => y >= -2048 && y <= 2047), { last: 4800 }));\n"},{"id":"F-09","title":"Pipelines","group":"Components","about":"RGB to luma in three stages. What a stage writes is visible to the stages after it, and pipeline.registers carries only what is still live: $.r, $.g and $.b cross one register, px crosses none. When the output is not ready the pipe stalls; .stall(\"skid\") spends a few registers to keep that stall off the critical path.","shows":["pipeline()",".stage()","inferred pipeline registers","fixed-point weights from build-time JS","a JS model"],"watch":"DAG (stages) · Waves","tries":["Add a contrast stage between sum and round","Switch to .stall(\"global\") and compare fmax"],"file":"F-09-pipelines.js","text":"/** F-09 Pipelines\n *  group  Components\n *  about  RGB to luma in three stages. What a stage writes is visible to the stages after it, and\n *         pipeline.registers carries only what is still live: $.r, $.g and $.b cross one register, px crosses none.\n *         When the output is not ready the pipe stalls; .stall(\"skid\") spends a few registers to keep that stall\n *         off the critical path.\n *  shows  pipeline() · .stage() · inferred pipeline registers · fixed-point weights from build-time JS · a JS model\n *  watch  DAG (stages) · Waves\n *  try    Add a contrast stage between sum and round | Switch to .stall(\"global\") and compare fmax\n */\nconst rgb = struct({ r: u(8), g: u(8), b: u(8) });\nconst W = [0.299, 0.587, 0.114].map(w => Math.round(w * 256));   // [77, 150, 29] in Q0.8, computed now\n\nconst luma = pipeline(\"luma\")\n  .needs(\"rgb\").provides(\"gray\")\n  .lib({ W })\n  .stall(\"skid\")\n  .stage(\"weigh\", ($, px) => {                      // the first stage receives the beat\n    $.r = px.r * W[0];\n    $.g = px.g * W[1];\n    $.b = px.b * W[2];\n  })\n  .stage(\"sum\", $ => { $.y = $.r + $.g + $.b; })    // as wide as it needs to be\n  .stage(\"round\", $ => sat(($.y + 128) >> 8, u(8)));   // the last stage's return value is the output beat\n\nreturn design(\"luma\")\n  .board(\"dev\")\n  .use(stream(\"rgb\").of(rgb), stream(\"gray\").of(u(8)), luma)\n  .scenario(\"matches the JS model\", async tb => {   // runtime lambda: async JS beside the simulator\n    const px = Array.from({ length: 64 }, () =>\n      ({ r: tb.random.int(0, 255), g: tb.random.int(0, 255), b: tb.random.int(0, 255) }));\n    await tb.push(\"rgb\", px);\n    const ys = await tb.pull(\"gray\", px.length);\n    px.forEach((p, i) =>\n      tb.expectEqual(ys[i], Math.min(255, (p.r * W[0] + p.g * W[1] + p.b * W[2] + 128) >> 8), `pixel ${i}`));\n  })\n  .scenario(\"survives backpressure\", sc => sc\n    .feed(\"rgb\", \"random\", { beats: 500 })\n    .throttle(\"gray\", { ready: 0.3 })               // the sink is ready on 30 % of cycles\n    .expectStream(\"gray\", ys => ys.length === 500, { within: \"100us\" }));\n"},{"id":"F-10","title":"Clock domains","group":"Time","about":"A sprite bounces in the 100 MHz system domain and is drawn in a 25.175 MHz pixel domain from a PLL. The position crosses between them on a stream marked .cross(). Delete that line and checks.cdc refuses to build, naming both domains and the stream.","shows":[".clocks()",".domain()","stream().cross()","std.video","unsigned minus unsigned is signed"],"watch":"Board (HDMI) · DAG (one graph per domain)","tries":["Remove .cross() and read the diagnostic","Move the sprite once per frame instead of on a timer"],"file":"F-10-clock-domains.js","text":"/** F-10 Clock domains\n *  group  Time\n *  about  A sprite bounces in the 100 MHz system domain and is drawn in a 25.175 MHz pixel domain from a PLL. The\n *         position crosses between them on a stream marked .cross(). Delete that line and checks.cdc refuses to\n *         build, naming both domains and the stream.\n *  shows  .clocks() · .domain() · stream().cross() · std.video · unsigned minus unsigned is signed\n *  watch  Board (HDMI) · DAG (one graph per domain)\n *  try    Remove .cross() and read the diagnostic | Move the sprite once per frame instead of on a timer\n */\nconst position = stream(\"sprite.pos\")\n  .of(struct({ x: u(10), y: u(10) }))\n  .buffer(1, { overflow: \"latest\" })                // only the newest position matters…\n  .cross({ from: \"sys\", to: \"pix\" });               // …so the crossing is a handshake synchronizer, not a FIFO\n\nconst physics = module(\"physics\")\n  .provides(\"sprite.pos\")\n  .lib({ MAX_X: 640 - 16, MAX_Y: 480 - 16 })\n  .regs({ x: u(10).init(40), y: u(10).init(30), left: bit, up: bit })\n  .every(\"8ms\", $ => {\n    const left = $.x === 0 ? 0 : $.x === MAX_X ? 1 : $.left;\n    const up = $.y === 0 ? 0 : $.y === MAX_Y ? 1 : $.up;\n    $.left = left;\n    $.up = up;\n    if (left) $.x -= 1; else $.x += 1;\n    if (up) $.y -= 1; else $.y += 1;\n    $.push(\"sprite.pos\", { x: $.x, y: $.y });\n  });\n\nconst raster = module(\"raster\")\n  .domain(\"pix\")\n  .needs(\"sprite.pos\", \"beam\")                      // beam: { x, y, visible } from std.video.timing\n  .provides(\"pixels\")\n  .regs({ sx: u(10), sy: u(10) })\n  .on(\"sprite.pos\", ($, p) => { $.sx = p.x; $.sy = p.y; })\n  .on(\"beam\", ($, b) => {\n    const dx = b.x - $.sx, dy = b.y - $.sy;         // u10 − u10 is s11: left of the sprite stays negative\n    const inside = dx >= 0 && dx < 16 && dy >= 0 && dy < 16;\n    $.push(\"pixels\", inside ? { r: 255, g: 200, b: 0 } : { r: 0, g: 0, b: b.y.bits(8, 1) });\n  });\n\nreturn design(\"bounce\")\n  .board(\"dev\")\n  .clocks(c => c\n    .pin(\"sys\", \"clk\")                              // 100 MHz from the board\n    .pll(\"pix\", { from: \"sys\", hz: \"25.175 MHz\", tolerance: \"0.5%\" }))   // the compiler solves the dividers\n  .use(position, physics, raster)\n  .use(\n    std.video.timing(\"beam\").mode(\"640x480@60\").domain(\"pix\"),\n    std.video.hdmi(\"hdmi\").domain(\"pix\").bind({ tmds: \"hdmi\" }))    // asks .clocks() for pix × 5 by itself\n  .scenario(\"draws a 16 × 16 sprite\", sc => sc\n    .wait(\"40ms\")\n    .expectFrame(\"hdmi\", f => f.count({ r: 255, g: 200, b: 0 }) === 256))\n  .scenario(\"bounces off the right edge\", sc => sc\n    .poke(\"physics.x\", 620).wait(\"50ms\")\n    .expectState(\"physics\", s => s.left === 1));\n"},{"id":"F-11","title":"Proofs and testbenches","group":"Verification","about":"A round-robin arbiter with its properties beside it. The same .assert() lambdas are checked on every cycle in simulation, proved by the formal engine, and can be built into hardware as monitors. A seeded, scoreboarded random test runs as an async runtime lambda.","shows":[".require() on params",".assert() / .assume() / .cover()","past() and within()",".prove()","coverage"],"watch":"Proofs · Waves","tries":["Break the rotation and read the counterexample trace","Prove it for N = 8"],"file":"F-11-proofs.js","text":"/** F-11 Proofs and testbenches\n *  group  Verification\n *  about  A round-robin arbiter with its properties beside it. The same .assert() lambdas are checked on every\n *         cycle in simulation, proved by the formal engine, and can be built into hardware as monitors. A seeded,\n *         scoreboarded random test runs as an async runtime lambda.\n *  shows  .require() on params · .assert() / .assume() / .cover() · past() and within() · .prove() · coverage\n *  watch  Proofs · Waves\n *  try    Break the rotation and read the counterexample trace | Prove it for N = 8\n */\nconst arbiter = module(\"arbiter\")\n  .params({ N: 4 })\n  .require(({ N }) => (N & (N - 1)) === 0 || \"N must be a power of two\")   // checked per specialization\n  .in(\"req\", ({ N }) => u(N))\n  .out(\"grant\", ({ N }) => u(N))\n  .regs(({ N }) => ({ last: u(clog2(N)) }))\n  .comb($ => {\n    $.grant = 0;\n    for (let k = N; k >= 1; k--) {                  // unrolled; the last match wins, so walk from the far end\n      const i = wrap($.last + k, u(clog2(N)));      // wrapping to clog2(N) bits is modulo N for free\n      if ($.req[i]) $.grant = 1 << i;\n    }\n  })\n  .seq($ => { for (let i = 0; i < N; i++) if ($.grant[i]) $.last = i; })\n  .assume(\"a request waits for its grant\", $ => !(past($.req[0]) && !past($.grant[0])) || $.req[0])\n  .assert(\"at most one grant\", $ => ($.grant & ($.grant - 1)) === 0)\n  .assert(\"grants go to requesters\", $ => ($.grant & ~$.req) === 0)\n  .assert(\"served within N cycles\", $ => !$.req[0] || within(N, $.grant[0]))\n  .cover(\"every port served in turn\", $ => sequence($.grant === 1, $.grant === 2, $.grant === 4, $.grant === 8));\n\nreturn design(\"arbiter\")\n  .use(arbiter)                                     // no board and no part: simulation and proofs only\n  .prove(p => p\n    .module(\"arbiter\")\n    .bmc(24)                                        // no counterexample in 24 cycles…\n    .induction()                                    // …then k-induction for every depth\n    .engine(\"smt\"))\n  .scenario(\"fair under random load\", async tb => {\n    const served = [0, 0, 0, 0];\n    let req = 0, grant = 0;\n    for (let t = 0; t < 10_000; t++) {\n      req = (req & ~grant) | tb.random.int(0, 15);  // pending requests stay up, as the assume demands\n      await tb.poke(\"arbiter.req\", req);\n      await tb.step();\n      grant = await tb.peek(\"arbiter.grant\");\n      if (grant) served[Math.log2(grant)]++;\n    }\n    tb.expect(Math.min(...served) > 2000, `shares: ${served}`);   // seeded: a failure replays exactly\n    tb.expectCoverage(\"all\");                       // every .cover() was hit at least once\n  });\n"},{"id":"F-12","title":"Knobs","group":"Runtime","about":"Modules declare what may be turned while the design runs. csr.collect gathers every knob, status and irq into one register map behind a bus bridge, and the backends emit a C header, a typed JS driver and the register docs. The host panel is a runtime lambda that turns knobs over UART; the bitstream never changes.","shows":[".knob() with bounds enforced in hardware",".status()",".irq()","a bus bridge","host()","emitted drivers"],"watch":"Board (audio) · Registers","tries":["Give the panel a vibrato-depth knob","Raise the volume ceiling and hear the clip counter climb"],"file":"F-12-knobs.js","text":"/** F-12 Knobs\n *  group  Runtime\n *  about  Modules declare what may be turned while the design runs. csr.collect gathers every knob, status and irq\n *         into one register map behind a bus bridge, and the backends emit a C header, a typed JS driver and the\n *         register docs. The host panel is a runtime lambda that turns knobs over UART; the bitstream never changes.\n *  shows  .knob() with bounds enforced in hardware · .status() · .irq() · a bus bridge · host() · emitted drivers\n *  watch  Board (audio) · Registers\n *  try    Give the panel a vibrato-depth knob | Raise the volume ceiling and hear the clip counter climb\n */\nconst sine = rom(\"sine\")\n  .of(s(12))\n  .from(1024, i => Math.round(2047 * Math.sin((2 * Math.PI * i) / 1024)));\n\nconst synth = module(\"synth\")\n  .provides(\"samples\")\n  .knob(\"hz\", u(14), { reset: 440, min: 20, max: 8000 })   // a write outside the bounds saturates, in hardware\n  .knob(\"volume\", u(4), { reset: 8 })\n  .status(\"clipped\", u(16))                         // hardware writes it, the host reads it\n  .irq(\"clip\")                                      // a pulse here arrives at the host as an event\n  .lib({ SINE: sine, K: Math.round(2 ** 32 / 48_000) })\n  .regs({ phase: u(32) })\n  .every(\"48 kHz\", $ => {\n    $.phase += $.hz * K;\n    const y = (SINE[$.phase.bits(31, 22)] * $.volume) >> 3;\n    if (y > 2047 || y < -2048) { $.clipped += 1; $.clip = 1; }\n    $.push(\"samples\", sat(y, s(12)));\n  });\n\nconst panel = host(\"panel\")\n  .over(\"bridge\")                                   // the bridge's other end: a serial port, or the simulator\n  .onStart(async dev => dev.log(await dev.registers()))   // the map the compiler built\n  .every(\"20ms\", async dev => {                     // runtime lambda: ordinary JS on your machine\n    const t = dev.clock.seconds();\n    await dev.knob(\"synth.hz\").set(Math.round(660 + 220 * Math.sin(Math.PI * t)));   // a siren, no rebuild\n  })\n  .on(\"synth.clip\", async dev => {\n    await dev.knob(\"synth.volume\").update(v => Math.max(v - 1, 0));\n    dev.log(\"clipped\", await dev.status(\"synth.clipped\").read(), \"times; volume down\");\n  });\n\nreturn design(\"siren\")\n  .board(\"dev\")\n  .use(synth, panel)\n  .use(\n    std.sigmaDelta(\"dac\").needs(\"samples\").bind({ out: \"audio\" }),\n    std.bridge.uart(\"bridge\").baud(1_000_000).bind({ uart: \"uart\" }))   // how the host reaches the map\n  .compile(c => c\n    .emit(\"c-header\", { to: \"fw/siren_regs.h\" })\n    .emit(\"host-js\", { to: \"host/siren.js\" })      // dev.knob(\"synth.hz\"), typed, with bounds and docs\n    .emit(\"register-doc\", { to: \"docs/registers.md\" }))\n  .scenario(\"bounds hold in hardware\", sc => sc\n    .write(\"synth.hz\", 50_000).expectKnob(\"synth.hz\", 8000)\n    .write(\"synth.hz\", 3).expectKnob(\"synth.hz\", 20))\n  .scenario(\"the panel turns the volume down on clipping\", sc => sc\n    .write(\"synth.volume\", 15)\n    .run(\"panel\").wait(\"100ms\")\n    .expectKnob(\"synth.volume\", v => v < 15));\n"},{"id":"F-13","title":"The pass pipeline","group":"Compiler","about":"Under every design is an IR DAG compiler. Hardware lambdas are parsed into HIR, flattened into one dataflow DAG per clock domain (registers are where the cycles are cut), optimized to a fixpoint, mapped onto the part's cells, then placed and routed. Every node keeps the lambda and the source text it came from, through every pass. This is what .compile() runs when you pass nothing, written out, with a snapshot, an inspection and checks between stages.","shows":["hir → dag → net → phys","stages and passes","fixpoint","verifyEach","snapshot","inspect","checks"],"watch":"Passes · DAG · Report","tries":["Drop dsp.pack and compare LUTs","Ask for 400 MHz and follow explain() back to the source"],"file":"F-13-pass-pipeline.js","text":"/** F-13 The pass pipeline\n *  group  Compiler\n *  about  Under every design is an IR DAG compiler. Hardware lambdas are parsed into HIR, flattened into one\n *         dataflow DAG per clock domain (registers are where the cycles are cut), optimized to a fixpoint, mapped\n *         onto the part's cells, then placed and routed. Every node keeps the lambda and the source text it came\n *         from, through every pass. This is what .compile() runs when you pass nothing, written out, with a\n *         snapshot, an inspection and checks between stages.\n *  shows  hir → dag → net → phys · stages and passes · fixpoint · verifyEach · snapshot · inspect · checks\n *  watch  Passes · DAG · Report\n *  try    Drop dsp.pack and compare LUTs | Ask for 400 MHz and follow explain() back to the source\n */\nconst mac = module(\"mac\")\n  .in({ a: s(18), b: s(18), clear: bit })\n  .out(\"acc\", s(48))\n  .seq($ => {\n    if ($.clear) $.acc = 0;\n    else $.acc += $.a * $.b;                        // 18 × 18 → 36 bits; dsp.pack folds the multiply-add into one DSP\n  });\n\n// What .inspect(\"dag\", g => g.print(), { after: \"optimize\" }) shows: one line per node, each with its origin:\n//   %1 = in a : s18\n//   %2 = in b : s18\n//   %3 = in clear : bit\n//   %4 = reg acc : s48                       ← .out(\"acc\", s(48)), written in .seq\n//   %5 = mul %1, %2 : s36                    ← $.a * $.b\n//   %6 = add %4, sext(%5) : s48 wrap         ← +=\n//   %7 = mux %3, 0, %6 : s48                 ← if ($.clear)\n//   %4.next = %7\n\nreturn design(\"mac\")\n  .part(\"xc7a35t-1\")                                // no board: an IP block, and its ports are the top\n  .clocks(c => c.port(\"sys\", { hz: \"250 MHz\" }))\n  .use(mac)\n  .compile(c => c\n    .cache(\".weft/cache\")                           // nodes are content-hashed: an edit rebuilds only what it reaches\n    .stage(\"front\", s => s                          // source → hir\n      .pass(std.passes.parse)                       // hardware lambdas → HIR, with the capture check\n      .pass(std.passes.elaborate)                   // params, .with(), generator loops → one instance tree\n      .pass(std.passes.link))                       // provides/needs and .wire() → edges; unmet needs fail here\n    .stage(\"lower\", s => s                          // hir → dag\n      .pass(std.passes.fsm.extract, std.passes.pipeline.registers, std.passes.stream.lower, std.passes.csr.collect)\n      .pass(std.passes.flatten)                     // one DAG per clock domain; registers are its sources and sinks\n      .pass(std.passes.widths)                      // infer, then enforce: nothing truncates silently\n      .pass(std.passes.checks.loops, std.passes.checks.latches, std.passes.checks.cdc))\n    .stage(\"optimize\", s => s\n      .pass(std.passes.constFold, std.passes.cse, std.passes.muxTree, std.passes.dce)\n      .fixpoint({ max: 8 }))                        // repeat until the graph's hash stops changing\n    .stage(\"time\", s => s                           // moves latency only where .pipelined() allows it\n      .pass(std.passes.pipeline.cut, std.passes.retime))\n    .stage(\"map\", s => s                            // dag → net\n      .pass(std.passes.mem.infer, std.passes.dsp.pack, std.passes.fsm.encode)\n      .pass(std.passes.techmap))                    // the part decides the cells: LUT6, CARRY4, DSP48E1 …\n    .stage(\"back\", s => s                           // net → phys\n      .pass(std.passes.place.with({ effort: \"high\" }), std.passes.route, std.passes.timing))\n    .verifyEach()                                   // re-check IR invariants after every pass: slower, catches pass bugs\n    .snapshot(\"dag\", { after: \"optimize\", as: \"dot\", to: \"build/mac.dag.dot\" })\n    .inspect(\"net\", net => console.log(net.stats()), { after: \"map\" })   // a builder lambda over the IR, mid-build\n    .check(\"one DSP\", r => r.resources.dsps === 1 || `used ${r.resources.dsps} DSPs`)\n    .check(\"meets 250 MHz\", r => r.timing.slack(\"sys\") >= 0 || r.timing.worst(\"sys\").explain())   // path → source\n    .emit(\"verilog\", { to: \"build/rtl\" })\n    .emit(\"report\", { to: \"build/mac.report.json\" }))\n  .scenario(\"accumulates\", sc => sc\n    .poke(\"mac.a\", 3).poke(\"mac.b\", -4).step(5)\n    .expectSignal(\"mac.acc\", -60));\n"},{"id":"F-14","title":"Your own passes","group":"Compiler","about":"Passes are values, like modules. An analysis computes a fact about the IR; a pass changes it; a rewrite is a pattern and its replacement, both written as hardware lambdas and matched against the DAG. requires/preserves turn the pass list into a DAG of its own, so an analysis reruns only after something invalidated it. The same scenario runs at three IR levels; a mismatch names the pass that caused it.","shows":["analysis()","pass().visit()","rewrite().from().where().to()","rule examples","e-graph saturation","lint"],"watch":"Passes · DAG","tries":["Add a rule for x * 2^k - x","Lower the fanout limit to 8 and watch the register count"],"file":"F-14-own-passes.js","text":"/** F-14 Your own passes\n *  group  Compiler\n *  about  Passes are values, like modules. An analysis computes a fact about the IR; a pass changes it; a rewrite\n *         is a pattern and its replacement, both written as hardware lambdas and matched against the DAG.\n *         requires/preserves turn the pass list into a DAG of its own, so an analysis reruns only after something\n *         invalidated it. The same scenario runs at three IR levels; a mismatch names the pass that caused it.\n *  shows  analysis() · pass().visit() · rewrite().from().where().to() · rule examples · e-graph saturation · lint\n *  watch  Passes · DAG\n *  try    Add a rule for x * 2^k - x | Lower the fanout limit to 8 and watch the register count\n */\nconst isPow2 = k => k > 0 && (k & (k - 1)) === 0;\n\nconst peephole = [\n  rewrite(\"multiply by a power of two\")\n    .from((x, k) => x * k)                          // a pattern: x and k match any node…\n    .where(({ k }) => k.isConst && isPow2(k.value)) // …and this builder lambda narrows the match\n    .to((x, k) => x << clog2(k))\n    .examples([[x => x * 8, x => x << 3], [x => x * 6, null]]),   // null: must not match\n  rewrite(\"same value on both arms\").from((c, a) => (c ? a : a)).to((c, a) => a),\n  rewrite(\"double inversion\").from(x => ~~x).to(x => x),\n];   // SAT screens each rule at widths 1–16 when loaded, then proves it again at the exact width of each match\n\nconst fanout = analysis(\"fanout\")\n  .on(\"dag\")\n  .run(g => new Map(g.nodes().map(n => [n.id, n.users.length])));\n\nconst splitFanout = pass(\"split-fanout\")\n  .on(\"dag\")\n  .requires(fanout, std.analyses.timing)            // estimated on the DAG, long before placement\n  .preserves(\"widths\", \"domains\")                   // everything else is invalidated when this pass edits the graph\n  .params({ limit: 32 })\n  .visit(\"reg\", (n, g, { fanout, timing, limit }) => {\n    const users = fanout.get(n.id);\n    if (users > limit && timing.slack(n) < 0.5) g.duplicate(n, { copies: Math.ceil(users / limit), split: \"users\" });\n  });\n\nconst wideCompares = pass(\"lint: wide comparisons\")\n  .on(\"dag\")\n  .readonly()                                       // preserves every analysis\n  .visit([\"lt\", \"le\", \"gt\", \"ge\"], (n, g) => {\n    const w = Math.max(...n.args.map(a => a.width));   // the result is one bit; the operands carry the width\n    if (w > 32) g.warn(n, `${w}-bit comparison in one cycle`);   // reported at the lambda's source line\n  });\n\nconst scaler = module(\"scaler\")\n  .in({ x: u(16), en: bit, now: u(48), deadline: u(48) })\n  .out({ y: vec(u(20), 64), late: bit })\n  .regs({ go: bit })                                // en, registered once: one flip-flop that drives 1280 enables\n  .seq($ => {\n    $.go = $.en;\n    for (let i = 0; i < 64; i++) if ($.go) $.y[i] = ($.x ^ i) * 8;   // 64 multiplies by 8\n  })\n  .comb($ => { $.late = $.now > $.deadline; });    // 48 bits: the lint will say so\n\nreturn design(\"passes\")\n  .part(\"ice40up5k-sg48\")\n  .clocks(c => c.port(\"sys\", { hz: \"48 MHz\" }))\n  .use(scaler)\n  .compile(c => c\n    .use(std.pipeline.default)                      // F-13's stages, then edits to them\n    .after(\"lower\", s => s.pass(wideCompares))\n    .after(\"optimize\", s => s.pass(std.passes.saturate(peephole, { iters: 6, cost: \"luts\" })))   // e-graph, cheapest wins\n    .before(\"techmap\", s => s.pass(splitFanout.with({ limit: 16 })))\n    .explainPlan()                                  // prints the pass DAG: what ran, what was reused, what was invalidated\n    .check(\"no multipliers left\", r => r.ir(\"dag\").count(\"mul\") === 0))\n  .scenario(\"same answers after the rewrites\", sc => sc\n    .poke(\"scaler.x\", 1000).poke(\"scaler.en\", 1).step(2)   // one edge to register en, one to load y\n    .expectSignal(\"scaler.y[5]\", (1000 ^ 5) * 8),\n    { levels: [\"hir\", \"dag\", \"net\"] });             // run at three IR levels; a mismatch is bisected to one pass\n"},{"id":"F-15","title":"Retiming and exploration","group":"Compiler","about":"A 31-tap FIR filter written as one combinational sum. .pipelined() hands the latency of its stream path to the compiler, so pipeline.cut slices the adder tree to meet the clock and retime moves registers across it. .explore() runs the pipeline over a grid of build-time knobs and keeps the Pareto front; the IR cache makes every point after the first a partial rebuild. Build-time knobs pick parameters; runtime knobs (F-12) are registers.","shows":["taps from build-time JS",".hint()",".pipelined()","pipeline.cut","retime","explore()","a JS reference model"],"watch":"Report (explore) · DAG","tries":["Add a \"fold symmetric taps\" knob","Keep only points with latency ≤ 6 and see which survive"],"file":"F-15-retime-explore.js","text":"/** F-15 Retiming and exploration\n *  group  Compiler\n *  about  A 31-tap FIR filter written as one combinational sum. .pipelined() hands the latency of its stream path to\n *         the compiler, so pipeline.cut slices the adder tree to meet the clock and retime moves registers across\n *         it. .explore() runs the pipeline over a grid of build-time knobs and keeps the Pareto front; the IR cache\n *         makes every point after the first a partial rebuild. Build-time knobs pick parameters; runtime knobs\n *         (F-12) are registers.\n *  shows  taps from build-time JS · .hint() · .pipelined() · pipeline.cut · retime · explore() · a JS reference model\n *  watch  Report (explore) · DAG\n *  try    Add a \"fold symmetric taps\" knob | Keep only points with latency ≤ 6 and see which survive\n */\nfunction lowpass(n, cutoff) {                       // windowed sinc, normalized to unity gain in Q15: plain JS\n  const m = (n - 1) / 2;\n  const h = Array.from({ length: n }, (_, i) => {\n    const t = i - m;\n    const sinc = t === 0 ? 2 * cutoff : Math.sin(2 * Math.PI * cutoff * t) / (Math.PI * t);\n    return sinc * (0.54 - 0.46 * Math.cos((2 * Math.PI * i) / (n - 1)));   // Hamming window\n  });\n  const sum = h.reduce((a, b) => a + b, 0);\n  return h.map(v => Math.round((v / sum) * 2 ** 15));\n}\n\nconst fir = module(\"fir\")\n  .params({ TAPS: 31, CUTOFF: 0.1, MULT: \"dsp\" })\n  .needs(\"in\").provides(\"out\")\n  .lib(({ TAPS, CUTOFF }) => ({ H: lowpass(TAPS, CUTOFF) }))\n  .regs(({ TAPS }) => ({ z: vec(s(16), TAPS) }))   // the delay line\n  .hint(({ MULT }) => ({ multiply: MULT }))         // \"dsp\" | \"lut\" | \"shift-add\": steers dsp.pack and techmap\n  .pipelined({ path: [\"in\", \"out\"] })               // latency on this stream path is the compiler's to choose\n  .on(\"in\", ($, x) => {\n    for (let i = TAPS - 1; i > 0; i--) $.z[i] = $.z[i - 1];\n    $.z[0] = x;\n    let acc = x * H[0];\n    for (let i = 1; i < TAPS; i++) acc = acc + $.z[i - 1] * H[i];   // grows as it must; nothing truncates\n    $.push(\"out\", sat(acc >> 15, s(16)));\n  });\n\nreturn design(\"fir\")\n  .board(\"dev\")\n  .use(stream(\"in\").of(s(16)), stream(\"out\").of(s(16)), fir)\n  .compile(c => c\n    .use(std.pipeline.default)                      // F-13's stages, then one edit to them\n    .replace(\"retime\", std.passes.retime.with({ moves: \"both\" }))   // registers may move backward too\n    .explore(x => x\n      .knob(\"fir.TAPS\", [15, 31, 63])\n      .knob(\"fir.MULT\", [\"dsp\", \"lut\", \"shift-add\"])\n      .knob(\"clock.sys\", [\"100 MHz\", \"150 MHz\", \"200 MHz\"])\n      .measure(r => ({\n        luts: r.resources.luts,\n        dsps: r.resources.dsps,\n        latency: r.latency(\"fir\"),\n        met: r.timing.slack(\"sys\") >= 0,\n      }))\n      .keep(m => m.met)\n      .pareto([\"luts\", \"dsps\", \"latency\"])\n      .parallel(8)\n      .report(\"build/fir-explore.html\")))\n  .scenario(\"matches the JS model\", async tb => {\n    const H = lowpass(31, 0.1);                     // runtime lambdas may call build-time JS freely\n    const xs = Array.from({ length: 200 }, () => tb.random.int(-20_000, 20_000));\n    await tb.push(\"in\", xs);\n    const ys = await tb.pull(\"out\", xs.length);\n    xs.forEach((_, n) => {\n      const acc = H.reduce((a, h, i) => a + h * (xs[n - i] ?? 0), 0);\n      tb.expectEqual(ys[n], Math.max(-32_768, Math.min(32_767, Math.floor(acc / 2 ** 15))), `y[${n}]`);\n    });\n  });\n"},{"id":"F-16","title":"Many parts, many backends","group":"Compiler","about":"The DAG knows nothing about the part until techmap, so boards with the same clock share every pass before it: dev and big (100 MHz) share one DAG, and pico (12 MHz) gets its own, because the UART dividers are computed from the clock. It emits Verilog and VHDL per part, a cycle-accurate WebAssembly model per DAG, and a cell census from a backend of your own. One scenario runs behaviorally and gate-level on every part.","shows":[".boards()","board().part()","c.when() per target","emit()","backend()","scenarios across IR levels"],"watch":"Report (per target) · Passes","tries":["Emit FIRRTL as well","Give the pico build a 32 KB line buffer in SPRAM"],"file":"F-16-targets.js","text":"/** F-16 Many parts, many backends\n *  group  Compiler\n *  about  The DAG knows nothing about the part until techmap, so boards with the same clock share every pass before\n *         it: dev and big (100 MHz) share one DAG, and pico (12 MHz) gets its own, because the UART dividers are\n *         computed from the clock. It emits Verilog and VHDL per part, a cycle-accurate WebAssembly model per DAG,\n *         and a cell census from a backend of your own. One scenario runs behaviorally and gate-level on every part.\n *  shows  .boards() · board().part() · c.when() per target · emit() · backend() · scenarios across IR levels\n *  watch  Report (per target) · Passes\n *  try    Emit FIRRTL as well | Give the pico build a 32 KB line buffer in SPRAM\n */\nconst upcase = module(\"upcase\")\n  .needs(\"rx.bytes\").provides(\"tx.bytes\")\n  .on(\"rx.bytes\", ($, c) => {\n    $.push(\"tx.bytes\", c >= 97 && c <= 122 ? c ^ 0x20 : c);   // flip bit 5: a → A\n  });\n\nconst census = backend(\"cell-census\")\n  .on(\"net\")                                        // after techmap, once per target\n  .emit((net, out) => {\n    const counts = {};\n    for (const cell of net.cells()) counts[cell.type] = (counts[cell.type] ?? 0) + 1;\n    out.file(\"cells.json\", JSON.stringify(counts, null, 2));\n  });\n\nreturn design(\"shout\")\n  .boards({\n    pico: board(\"pico\"),                            // ice40up5k\n    dev: board(\"dev\"),                              // xc7a35t\n    big: board(\"dev\").part(\"xc7a100t-1csg324\"),     // a board profile is a copy you can change\n  })\n  .use(\n    std.uart.rx(\"rx\").baud(115_200).bind({ rx: \"uart.rx\" }).provides(\"rx.bytes\"),\n    upcase,\n    std.uart.tx(\"tx\").baud(115_200).bind({ tx: \"uart.tx\" }).needs(\"tx.bytes\"))\n  .compile(c => c\n    .when(t => t.family === \"xc7\", w => w.after(\"map\", s => s.pass(std.passes.srl.infer)))   // LUTs as shift registers\n    .emit(\"verilog\", { to: t => `build/${t.name}/rtl` })   // a builder lambda, once per target\n    .emit(\"vhdl\", { to: t => `build/${t.name}/vhdl` })\n    .emit(\"sim:wasm\", { to: t => `build/${t.name}/shout.wasm`, level: \"dag\" })   // one model per distinct DAG\n    .emit(census, { to: t => `build/${t.name}` })\n    .check(\"small everywhere\", (r, t) => r.resources.luts < 0.2 * t.part.luts))\n  .scenario(\"shouts back\", sc => sc\n    .uart(\"uart\", \"hello, fabric\\n\")\n    .expectUart(\"uart\", \"HELLO, FABRIC\\n\", { within: \"3ms\" }),\n    { levels: [\"dag\", \"net\"], targets: \"all\" });    // two DAG runs (pico; dev and big), three net runs\n"},{"id":"F-17","title":"Hot swap, with rollback","group":"Live change","about":"The filter lives in a reconfigurable region. A change is linted, replayed against recorded traffic, built as a partial bitstream for that region alone (the rest of the design is locked), and loaded for a canary window while its asserts run as hardware monitors. A knob-only change is a register write and skips all of that. A good swap commits; a bad one trips an assert during canary and the previous partial comes back.","shows":[".regions()",".place()","change()",".knob()",".replace()",".patch()",".verify()",".deploy()",".migrate()"],"watch":"Changes · Board (audio) · Waves","tries":["Shorten the canary to 50 ms and watch the bad change commit","Patch the filter and a knob in one change"],"file":"F-17-hot-swap.js","text":"/** F-17 Hot swap, with rollback\n *  group  Live change\n *  about  The filter lives in a reconfigurable region. A change is linted, replayed against recorded traffic, built\n *         as a partial bitstream for that region alone (the rest of the design is locked), and loaded for a canary\n *         window while its asserts run as hardware monitors. A knob-only change is a register write and skips all\n *         of that. A good swap commits; a bad one trips an assert during canary and the previous partial comes back.\n *  shows  .regions() · .place() · change() · .knob() · .replace() · .patch() · .verify() · .deploy() · .migrate()\n *  watch  Changes · Board (audio) · Waves\n *  try    Shorten the canary to 50 ms and watch the bad change commit | Patch the filter and a knob in one change\n */\nfunction lowpass2(fc, fs) {                         // an RBJ biquad low-pass in Q14, plain JS at build time\n  const w = (2 * Math.PI * fc) / fs, alpha = Math.sin(w) / Math.SQRT2, c = Math.cos(w), a0 = 1 + alpha;\n  const q14 = v => Math.round((v / a0) * 2 ** 14);\n  return { B: [q14((1 - c) / 2), q14(1 - c), q14((1 - c) / 2)], A: [q14(-2 * c), q14(1 - alpha)] };\n}\n\nconst tone = module(\"tone\")\n  .provides(\"dry\")\n  .knob(\"volume\", u(4), { reset: 2 })\n  .lib({ STEP: Math.round((330 * 2 ** 16) / 48_000) })\n  .regs({ phase: u(16) })\n  .every(\"48 kHz\", $ => {\n    $.phase += STEP;\n    $.push(\"dry\", sat(($.phase.as(s(16)) * $.volume) >> 4, s(16)));   // .as() reinterprets: a sawtooth\n  });\n\nconst onePole = module(\"filter\")\n  .needs(\"dry\").provides(\"wet\")\n  .knob(\"alpha\", u(8), { reset: 32 })               // 0 holds still, 255 passes everything\n  .regs({ y: s(16) })\n  .on(\"dry\", ($, x) => {\n    $.y += ((x - $.y) * $.alpha) >> 8;\n    $.push(\"wet\", $.y);\n  })\n  .assert(\"never pinned at a rail\", $ => $.y !== 32767 && $.y !== -32768);   // sim, proofs, and a hardware monitor\n\nconst biquad = module(\"filter\")                     // same name and ports: a drop-in replacement\n  .needs(\"dry\").provides(\"wet\")\n  .lib({ ...lowpass2(2000, 48_000), GAIN: 1 })\n  .regs({ x1: s(16), x2: s(16), y1: s(16), y2: s(16), out: s(16) })\n  .on(\"dry\", ($, x) => {\n    const acc = B[0] * x + B[1] * $.x1 + B[2] * $.x2 - A[0] * $.y1 - A[1] * $.y2;\n    const y = sat(acc >> 14, s(16));\n    $.x2 = $.x1; $.x1 = x;\n    $.y2 = $.y1; $.y1 = y;\n    const out = sat(y * GAIN, s(16));               // gain after the feedback loop, never inside it\n    $.out = out;\n    $.push(\"wet\", out);\n  })\n  .assert(\"never pinned at a rail\", $ => $.out !== 32767 && $.out !== -32768)\n  .migrate(old => ({ y1: old.y, y2: old.y, out: old.y }));   // runtime lambda: the old region's registers, read back\n\nconst softer = change(\"softer\")\n  .knob(\"filter.alpha\", 12);                        // a register write: no bitstream, commits at once\n\nconst swap = change(\"biquad instead of one-pole\")\n  .replace(\"filter\", biquad)\n  .verify(v => v.lint().ports(\"same\").replay(\"last 1s\").timing())\n  .deploy(d => d.partial(\"dsp\").canary(\"300ms\", { watch: [\"asserts\", \"wet.rate\"] }))\n  .rollbackOn(\"assert\", \"stall\");\n\nconst louder = change(\"gain × 4\")\n  .patch(\"filter\", { lib: { GAIN: 4 } })            // re-elaborates one module; only its region is rebuilt\n  .verify(v => v.lint().replay(\"last 1s\"))          // the recorded second was quiet, so replay passes\n  .deploy(d => d.partial(\"dsp\").canary(\"500ms\"))\n  .rollbackOn(\"assert\");\n\nreturn design(\"hot-swap\")\n  .board(\"dev\")\n  .regions(r => r.partition(\"dsp\", { luts: 1500, dsps: 6 }))   // a floorplanned slot; everything else is static\n  .place({ filter: \"dsp\" })\n  .record({ streams: [\"dry\"], keep: \"2s\" })         // what .replay() feeds a candidate\n  .use(tone, onePole, std.sigmaDelta(\"dac\").needs(\"wet\").bind({ out: \"audio\" }))\n  .scenario(\"good commits, bad rolls back\", sc => sc\n    .wait(\"1s\")\n    .apply(softer).expectChange(\"softer\", \"committed\", { within: \"1ms\" })\n    .apply(swap).expectChange(/biquad/, \"committed\", { within: \"2s\" })\n    .expectState(\"filter\", s => s.y1 !== 0)         // migrate() carried the state across\n    .apply(louder).wait(\"100ms\")\n    .write(\"tone.volume\", 12)                       // the live signal gets loud mid-canary\n    .expectChange(\"gain × 4\", \"rolled-back\", { within: \"1s\" })\n    .expectStream(\"wet\", ys => ys.every(y => Math.abs(y) < 32_767), { last: 480 }));\n"},{"id":"F-18","title":"Timing closer","group":"Agents","about":"An agent takes part in the build. When timing fails, the compiler hands the closer a dossier: the critical path as DAG nodes, each carrying the lambda and source text it came from. The closer proposes a change; the change is linted, checked for equivalence and timed again before it waits for your approval.","shows":["agent()",".scope()","the timing dossier","provenance through passes","equivalence up to stream latency"],"watch":"Agent · Changes · Report (timing)","tries":["Let it commit knob changes without approval","Limit it to one proposal per build"],"file":"F-18-timing-closer.js","text":"/** F-18 Timing closer\n *  group  Agents\n *  about  An agent takes part in the build. When timing fails, the compiler hands the closer a dossier: the\n *         critical path as DAG nodes, each carrying the lambda and source text it came from. The closer proposes a\n *         change; the change is linted, checked for equivalence and timed again before it waits for your approval.\n *  shows  agent() · .scope() · the timing dossier · provenance through passes · equivalence up to stream latency\n *  watch  Agent · Changes · Report (timing)\n *  try    Let it commit knob changes without approval | Limit it to one proposal per build\n */\nconst closer = agent(\"closer\")\n  .model(\"claude\")\n  .guidelines(`You close timing on FPGA designs. Read the dossier's critical path and the source it came from.\nPrefer, in order: a knob within its bounds, latency on a stream path (.pipelined), a rewrite of the lambda.\nNever change ports, pins, clocks or stream types. Behavior must stay equivalent up to stream latency.`)\n  .scope(s => s.read(\"*\").propose(\"modules/*\", \"knobs/*\").never(\"pins\", \"clocks\", \"boot\", \"streams\"))\n  .budget({ proposals: 3, per: \"build\" })\n  .on(\"timing.failed\", async (ctx, d) => {          // d: { domain, target, slack, path: [{ op, width, origin }], resources }\n    const proposal = await ctx.llm.propose({\n      goal: `Meet ${d.target} in ${d.domain}; the worst slack is ${d.slack} ns`,\n      evidence: { path: d.path, resources: d.resources },\n    });\n    return ctx.changes.submit(proposal, {\n      verify: v => v.lint().equiv({ upTo: \"stream latency\" }).timing(),\n      approve: \"you\",                               // waits in the Changes tab\n    });\n  });\n\nconst blend = module(\"blend\")\n  .needs(\"layers\").provides(\"out\")\n  .lib({ GAMMA: Array.from({ length: 256 }, (_, i) => Math.round(255 * (i / 255) ** (1 / 2.2))) })\n  .on(\"layers\", ($, l) => {\n    const mix = (l.fg * l.alpha + l.bg * (255 - l.alpha) + 128) >> 8;   // two multiplies, two adds…\n    $.push(\"out\", GAMMA[sat(mix, u(8))]);                                 // …and a table, all in one cycle\n  });\n\nreturn design(\"blend\")\n  .board(\"dev\")\n  .clocks(c => c.pin(\"sys\", \"clk\").pll(\"fast\", { from: \"sys\", hz: \"300 MHz\" }))\n  .use(stream(\"layers\").of(struct({ fg: u(8), bg: u(8), alpha: u(8) })), stream(\"out\").of(u(8)))\n  .use(blend.domain(\"fast\"), closer)                // .domain() returns a new value, like every builder call\n  .scenario(\"closes timing\", sc => sc\n    .build()\n    .expectBuild(\"timing\", \"failed\")                // the dossier goes to the closer\n    .expectProposal(\"closer\", { within: \"2m\" })\n    .approve()\n    .expectChange(/blend/, \"committed\")\n    .expectBuild(\"timing\", \"met\"))\n  .scenario(\"still blends\", sc => sc\n    .feed(\"layers\", [{ fg: 255, bg: 0, alpha: 255 }, { fg: 0, bg: 255, alpha: 0 }])\n    .expectStream(\"out\", ys => ys.every(y => y >= 254)));\n"},{"id":"F-19","title":"Arcade","group":"Whole designs","about":"Two-player pong on the studio board: buttons in, HDMI and audio out. The game is an fsm stepped once per frame; the picture is drawn in the pixel domain; knobs, a status counter and an irq reach a host panel over UART. Reset groups supervise like process trees, the boot order waits for the PLL, the renderer sits in a reconfigurable slot, and a mechanic is on call when the pixel path keeps falling over.","shows":["everything at once","fsm().step()","two crossings","groups as reset trees",".boot()","probes in a dossier"],"watch":"Board · DAG · Changes · Agent","tries":["Hang the encoder four times and approve the mechanic's fix","Add a third palette as a change"],"file":"F-19-arcade.js","text":"/** F-19 Arcade\n *  group  Whole designs\n *  about  Two-player pong on the studio board: buttons in, HDMI and audio out. The game is an fsm stepped once per\n *         frame; the picture is drawn in the pixel domain; knobs, a status counter and an irq reach a host panel\n *         over UART. Reset groups supervise like process trees, the boot order waits for the PLL, the renderer\n *         sits in a reconfigurable slot, and a mechanic is on call when the pixel path keeps falling over.\n *  shows  everything at once · fsm().step() · two crossings · groups as reset trees · .boot() · probes in a dossier\n *  watch  Board · DAG · Changes · Agent\n *  try    Hang the encoder four times and approve the mechanic's fix | Add a third palette as a change\n */\nconst scene = struct({ bx: u(10), by: u(9), p1: u(9), p2: u(9), size: u(7), s1: u(4), s2: u(4) });\n\nconst FONT = [\"111101101101111\", \"010110010010111\", \"111001111100111\", \"111001111001111\", \"101101111001001\",\n              \"111100111001111\", \"111100111101111\", \"111001001001001\", \"111101111101111\", \"111101111001111\"];\nconst glyphs = rom(\"glyphs\").of(u(15)).from(10, d => parseInt(FONT[d], 2));   // 3 × 5 digits, built from strings\n\nconst PALETTES = [\n  { fg: { r: 240, g: 240, b: 230 }, bg: { r: 16, g: 24, b: 40 } },   // day\n  { fg: { r: 255, g: 176, b: 0 }, bg: { r: 0, g: 0, b: 0 } },        // night\n];\n\n// ---------- streams: two of them cross clock domains ----------\nconst frames = stream(\"frame\").of(bit).cross({ from: \"pix\", to: \"sys\" });   // one beat per frame start\nconst scenes = stream(\"scene\").of(scene).buffer(1, { overflow: \"latest\" }).cross({ from: \"sys\", to: \"pix\" });\nconst sounds = stream(\"sfx\").of(struct({ hz: u(10), ms: u(9) })).buffer(4, { overflow: \"drop-oldest\" });\n\n// ---------- input ----------\nconst pads = std.debounce(\"pads\")\n  .bind({ raw: [\"btn:up\", \"btn:down\", \"btn:a\", \"btn:b\"] })\n  .settle(\"5ms\");                                   // .held: u(4), the debounced levels\n\n// ---------- the game, in the system domain ----------\nfunction movePaddles($) {                           // hardware helpers: shipped by .lib(), inlined where called\n  const bottom = H - $.paddle;\n  if ($.held[0] && $.p1 > 4) $.p1 -= 4;\n  if ($.held[1] && $.p1 < bottom) $.p1 += 4;\n  if ($.held[2] && $.p2 > 4) $.p2 -= 4;\n  if ($.held[3] && $.p2 < bottom) $.p2 += 4;\n}\nfunction hits(y, top, size) {\n  return y + BALL >= top && y <= top + size;\n}\n\nconst game = fsm(\"game\")\n  .in(\"held\", u(4))                                 // p1 up, p1 down, p2 up, p2 down\n  .needs(\"frame\").provides(\"scene\", \"sfx\")\n  .step(\"frame\")                                    // states run once per frame, not once per clock\n  .knob(\"speed\", u(3), { reset: 2, min: 1, max: 6 })\n  .knob(\"paddle\", u(7), { reset: 64, min: 24, max: 120 })\n  .status(\"rallies\", u(16))\n  .irq(\"point\")\n  .lib({ W: 640, H: 480, BALL: 8, movePaddles, hits })\n  .regs({\n    bx: u(10).init(316), by: u(9).init(236), vx: s(4), vy: s(4),\n    p1: u(9).init(208), p2: u(9).init(208), s1: u(4), s2: u(4), wait: u(7),\n  })\n  .seq($ => {                                       // every clock, offer the newest scene; the crossing keeps one\n    $.push(\"scene\", { bx: $.bx, by: $.by, p1: $.p1, p2: $.p2, size: $.paddle, s1: $.s1, s2: $.s2 });\n  })\n  .initial(\"serve\")\n  .state(\"serve\", $ => {\n    $.bx = 316; $.by = 236; $.vy = 1;\n    $.vx = $.s1 > $.s2 ? -$.speed : $.speed;        // serve toward whoever is ahead\n    $.wait += 1;\n    if ($.wait === 60) { $.wait = 0; return \"play\"; }   // a second of stillness\n  })\n  .state(\"play\", $ => {\n    movePaddles($);\n    const x = $.bx + $.vx, y = $.by + $.vy;         // u10 + s4 is s12: off-screen stays honest\n    if (y <= 0 || y >= H - BALL) { $.vy = $.vy > 0 ? -1 : 1; $.push(\"sfx\", { hz: 220, ms: 30 }); }\n    if (x <= 16 && hits(y, $.p1, $.paddle)) {\n      $.vx = $.speed; $.rallies += 1; $.push(\"sfx\", { hz: 440, ms: 40 });\n    } else if (x >= W - 24 && hits(y, $.p2, $.paddle)) {\n      $.vx = -$.speed; $.rallies += 1; $.push(\"sfx\", { hz: 440, ms: 40 });\n    } else if (x < 0 || x > W - BALL) {\n      if (x < 0) $.s2 += 1; else $.s1 += 1;\n      $.point = 1;\n      $.push(\"sfx\", { hz: 110, ms: 300 });\n      return \"point\";\n    }\n    $.bx = sat(x, u(10));\n    $.by = sat(y, u(9));\n  })\n  .state(\"point\", $ => {\n    $.wait += 1;\n    if ($.s1 === 9 || $.s2 === 9) return \"over\";\n    if ($.wait === 45) { $.wait = 0; return \"serve\"; }\n  })\n  .state(\"over\", $ => {\n    if ($.held !== 0) { $.s1 = 0; $.s2 = 0; $.wait = 0; return \"serve\"; }\n  });\n\n// ---------- the picture, in the pixel domain ----------\nfunction box(px, py, x, y, w, h) {\n  return px >= x && px < x + w && py >= y && py < y + h;\n}\nfunction digitAt(bx, by, x0, d) {                   // is the beam inside digit d, drawn 8× at (x0, 24)?\n  const cx = (bx - x0) >> 3, cy = (by - 24) >> 3;\n  return cx >= 0 && cx < 3 && cy >= 0 && cy < 5 && GLYPHS[d][14 - (cy * 3 + cx)];\n}\n\nconst renderer = module(\"renderer\")\n  .domain(\"pix\")\n  .needs(\"beam\", \"scene\").provides(\"pixels\")\n  .knob(\"palette\", u(1))                            // a knob in another domain is synchronized for you\n  .lib({ GLYPHS: glyphs, PALETTES, box, digitAt })\n  .regs({ sc: scene })\n  .on(\"scene\", ($, s) => { $.sc = s; })\n  .on(\"beam\", ($, b) => {\n    const s = $.sc;\n    const lit =\n      box(b.x, b.y, s.bx, s.by, 8, 8) ||\n      box(b.x, b.y, 8, s.p1, 8, s.size) ||\n      box(b.x, b.y, 624, s.p2, 8, s.size) ||\n      (b.x.bits(9, 1) === 160 && b.y[4]) ||         // the dashed net\n      digitAt(b.x, b.y, 260, s.s1) ||\n      digitAt(b.x, b.y, 356, s.s2);\n    const pal = PALETTES[$.palette];\n    $.push(\"pixels\", lit ? pal.fg : pal.bg);\n  })\n  .supervise(s => s.watchdog(\"20ms\", $ => $.has(\"beam\")).reset(\"local\"))   // no beam for 20 ms: reset\n  .probe(p => p.signals(\"sc\", \"palette\").depth(1024).keep(\"before-reset\"));   // the capture goes into dossiers\n\n// ---------- sound ----------\nconst beeper = module(\"beeper\")\n  .needs(\"sfx\").provides(\"samples\")\n  .lib({ K: Math.round(2 ** 24 / 48_000) })         // phase step per hertz\n  .regs({ phase: u(24), step: u(20), left: u(16) })\n  .on(\"sfx\", ($, e) => { $.step = e.hz * K; $.left = e.ms * 48; })\n  .every(\"48 kHz\", $ => {\n    if ($.left === 0) { $.push(\"samples\", 0); return; }\n    $.left -= 1;\n    $.phase += $.step;\n    $.push(\"samples\", $.phase[23] ? 6000 : -6000);  // a square wave, the way arcades did it\n  });\n\n// ---------- runtime: a host panel and a mechanic ----------\nconst panel = host(\"panel\")\n  .over(\"bridge\")\n  .on(\"game.point\", async dev => {\n    const rallies = await dev.status(\"game.rallies\").read();\n    if (rallies > 20) await dev.knob(\"game.speed\").update(v => v + 1);   // the ceiling of 6 is enforced in hardware\n    dev.log(`point after ${rallies} rallies`);\n  });\n\nconst mechanic = std.agents.mechanic\n  .scope(s => s\n    .read(\"*\")\n    .propose(\"modules/renderer\", \"modules/beeper\", \"knobs/*\")\n    .never(\"pins\", \"clocks\", \"boot\", \"streams\"));\n\n// ---------- the design ----------\nreturn design(\"arcade\")\n  .board(\"studio\")\n  .clocks(c => c.pin(\"sys\", \"clk\").pll(\"pix\", { from: \"sys\", hz: \"25.175 MHz\" }))\n  .use(frames, scenes, sounds, pads, game, renderer, beeper, panel, mechanic)\n  .use(\n    std.video.timing(\"beam\").mode(\"640x480@60\").domain(\"pix\").provides(\"beam\", \"frame\"),\n    std.video.hdmi(\"hdmi\").domain(\"pix\").bind({ tmds: \"hdmi\" }),\n    std.sigmaDelta(\"dac\").needs(\"samples\").bind({ out: \"audio\" }),\n    std.bridge.uart(\"bridge\").baud(1_000_000).bind({ uart: \"uart\" }))\n  .wire(\"pads.held\", \"game.held\")\n  .use(\n    group(\"video\")\n      .children(\"beam\", \"renderer\", \"hdmi\")\n      .supervise(s => s.strategy(\"all-for-one\").maxResets(3, \"10s\").escalate(\"mechanic\")),   // one stalls, all reset\n    group(\"audio\")\n      .children(\"beeper\", \"dac\")\n      .supervise(s => s.strategy(\"one-for-one\")))\n  .boot(b => b\n    .start(\"clocks\")                                // every reset is held until the PLL locks\n    .then(\"beam\", \"hdmi\")                           // a black screen first, never a torn one\n    .then(\"pads\", \"game\", \"renderer\")\n    .background(\"beeper\", \"dac\", \"bridge\"))\n  .regions(r => r.partition(\"gfx\", { luts: 2500, brams: 2 }))\n  .place({ renderer: \"gfx\" })                       // the mechanic's fixes ship as partial bitstreams\n  .compile(c => c\n    .check(\"room to grow\", r => r.resources.luts <= 0.7 * r.part.luts)\n    .check(\"pixel margin\", r => r.timing.slack(\"pix\") >= 2 || r.timing.worst(\"pix\").explain())\n    .emit(\"verilog\", { to: \"build/rtl\" })\n    .emit(\"host-js\", { to: \"host/arcade.js\" })\n    .emit(\"sim:wasm\", { to: \"build/arcade.wasm\" }))\n  .scenario(\"serve, rally, point\", sc => sc\n    .wait(\"1.1s\").expectState(\"game\", s => s.state === \"play\")\n    .expectIrq(\"game.point\", { within: \"6s\" })\n    .expectFrame(\"hdmi\", f => f.count(PALETTES[0].fg) > 0))\n  .scenario(\"paddles move\", sc => sc\n    .wait(\"1.1s\").press(\"btn:up\", { for: \"200ms\" })\n    .expectState(\"game\", s => s.p1 < 208))\n  .scenario(\"a stuck encoder resets the picture, not the game\", sc => sc\n    .wait(\"1s\").hang(\"hdmi\").wait(\"100ms\")\n    .expectResets(\"hdmi\", 1).expectResets(\"renderer\", 1).expectResets(\"game\", 0))\n  .scenario(\"night mode, no rebuild\", sc => sc\n    .apply(change(\"night\").knob(\"renderer.palette\", 1))\n    .wait(\"40ms\")\n    .expectFrame(\"hdmi\", f => f.count(PALETTES[1].bg) > 250_000))\n  .scenario(\"the mechanic on call\", sc => sc\n    .repeat(4, s => s.hang(\"hdmi\").wait(\"300ms\"))\n    .expectEscalation(\"video\", \"mechanic\")          // the dossier: resets, the probe capture, the source, nearby DAG\n    .approve()\n    .expectChange(/./, \"committed\", { within: \"3m\" }));\n"}];
